      const done = await this.claims.paste(this.text());
      if (typeof done === 'string') this.error.set(done);
      else {
        this.added.set(done);
        this.text.set('');
      }
    } finally {
      this.running.set(false);
    }
  }

  protected value(e: Event): string {
    return (e.target as HTMLTextAreaElement).value;
